\caption{Clustering metrics and random control comparison}
\label{tab:metrics}
\begin{tabular}{lrrrr}
\toprule
\textbf{Method} & \textbf{Silhouette} & \textbf{Calinski-Harabasz} & \textbf{Davies-Bouldin} & \textbf{Mean Pairwise ARI} \\
